  ctx.beginPath();
  ctx.moveTo(hubX, hubY + 4);
  ctx.bezierCurveTo(hubX - 5, 590, hubX + 6, 780, hubX, 896);
  ctx.strokeStyle = 'rgba(242, 234, 212, 0.28)';
