  seedGrad.addColorStop(0, 'rgba(175, 155, 123, 0.84)');
  seedGrad.addColorStop(0.45, 'rgba(209, 188, 152, 0.96)');
  seedGrad.addColorStop(0.75, 'rgba(190, 168, 132, 0.94)');
  seedGrad.addColorStop(1, 'rgba(155, 137, 108, 0.8)');
